  // #473 interactive web pages (webpage widget)
  'widget.web.interactive': "Interativo (quiosque walk-up)",
  'widget.web.interactive_hint': "Visitantes podem tocar, rolar e preencher formulários. A playlist pausa enquanto alguém usa a página, e depois que saem a página reseta e tudo que fizeram é apagado. Apenas tela cheia. Suporte completo no Android, players nativos Windows e Raspberry Pi e BrightSign; telas web, webOS e Tizen recebem uma versão limitada que não consegue limpar o site ou bloquear outros sites.",
  'widget.web.idle_timeout': "Resetar após tantos segundos sem toque",
  'widget.web.allowed_domains': "Outros sites que visitantes podem abrir",
  'widget.web.allowed_domains_ph': "ex. checkout.example.com, maps.example.com",
  'widget.web.allowed_domains_hint': "O próprio site da página é sempre permitido. Links para qualquer outro lugar são bloqueados.",
  'widget.web.home_button': "Mostrar um botão Home quando um visitante sair da página inicial",
  'widget.web.idle_warning': "\"Ainda está aí?\" contagem regressiva antes do reset",
  'widget.web.idle_warning_off': "Desligado (reseta imediatamente)",
  'widget.web.idle_warning_sec': "{n} segundos",
  'widget.web.idle_warning_hint': "Dá ao visitante um momento para tocar e continuar. Útil para lojas; em uma página de informação pode ficar desligado.",
  'widget.web.wipe_site_data': "Limpar cookies e armazenamento do site após cada visitante",
  'widget.web.wipe_site_data_hint': "Desligue para páginas de informação sem nada a proteger (cardápios, listas de preços, mapas): o banner de cookies e o idioma escolhido ficam. Cada visitante ainda recebe uma página nova, histórico e dados de formulário. O armazenamento é compartilhado por todas as páginas web em uma tela, então a limpeza de outro item na mesma tela também limpa isso. Os players Windows e Raspberry Pi mantêm cookies, mas não armazenamento de site; BrightSign sempre limpa.",
  'widget.web.keep_consent': "Manter a escolha de consentimento de cookies do site entre visitantes",
  'widget.web.keep_consent_hint': "Apenas os cookies de consentimento dos sites permitidos são mantidos. Logins, carrinhos e todo o resto ainda são apagados após cada visitante. Ferramentas de consentimento que armazenam a escolha em localStorage em vez de cookie ainda perguntarão.",
  'widget.web.keep_cookie_names': "Outros nomes de cookies para manter",
  'widget.web.keep_cookie_names_ph': "ex. shop_consent, cc_*",
  'widget.web.keep_cookie_names_hint': "Ferramentas comuns de consentimento (Cookiebot, OneTrust, IAB TCF, CookieYes, Complianz, Borlabs, iubenda, Didomi e outras) já são reconhecidas. Um * no final corresponde a um prefixo. Nunca adicione um cookie de login ou carrinho aqui.",
  'widget.web.zoom_hint': "O zoom % acima também se aplica à página interativa: 150 faz um site desktop se organizar como se a tela tivesse dois terços do tamanho.",
