  'device.event.http_error': "Página web retornou erro",
  'device.event.renderer_gone': "Página web crashou",
  'device.event.webview_too_old': "Página web precisa de um WebView mais novo",
  'device.caps.web_interactive': "Páginas web interativas:",
  'device.caps.web_interactive_full': "completo (o site abre em seu próprio navegador; links fora dos sites permitidos são bloqueados e tudo é limpo após cada visitante)",
  'device.caps.web_interactive_framed': "limitado (o site roda em um frame: sites que recusam framing ficam em branco, e a tela não consegue bloquear outros sites ou limpar o que um visitante deixa, então um login pode sobreviver ao reset)",
