  'platform.rollouts.subtitle': "Novas versões do player chegam às telas em ondas, e param sozinhas se se saírem pior",
  'platform.rollouts.desc': "Uma nova versão do player Android, Pi ou Windows vai para 10% das telas daquela plataforma, depois 50%, depois todos, cada onda esperando até as telas atualizadas parecerem saudáveis. Se telas atualizadas crasharem ou escurecerem mais que as demais, o lançamento para sozinho e você recebe um e-mail. Telas Pi e Windows que pegaram uma versão parada são enviadas de volta à anterior. Android não pode voltar a uma versão anterior, então lá uma parada interrompe a propagação e a correção é um build mais novo. Telas no canal beta e um Force update pulam as ondas.",
