  // 3.0: Simple help and the install-statistics question, now translated
  'simple.help.g1.title': 'Conectar uma tela',
  'simple.help.g1.s1': 'Na TV, tablet ou computador que você quer usar, abra o player: instale o app Android ou abra a página /player deste site no navegador.',
  'simple.help.g1.s2': 'Sem TV por perto? Abra o player em outra aba do navegador para testar.',
  'simple.help.g1.s3': 'O player mostra um código de 6 dígitos. Aqui, escolha “Adicionar uma tela” e digite-o.',
  'simple.help.g1.s4': 'Dê à tela um nome fácil de reconhecer, como “Vitrine”.',
  'simple.help.g2.title': 'Mudar o que uma tela mostra',
  'simple.help.g2.s1': 'Escolha “Mudar o que uma tela mostra” ou toque na tela em “Suas telas”.',
  'simple.help.g2.s2': 'Escolha “Substituir” para mostrar só o que é novo, ou “Adicionar” para manter o que já está passando.',
  'simple.help.g2.s3': 'Envie fotos ou vídeos, escolha alguns que você já enviou ou mostre o mesmo que outra tela.',
  'simple.help.g2.s4': 'A tela é atualizada em poucos segundos.',
  'simple.help.g3.title': 'Enviar fotos e vídeos',
  'simple.help.g3.s1': 'Escolha “Enviar fotos” e selecione quantos arquivos quiser, ou arraste-os.',
  'simple.help.g3.s2': 'Marque as telas que devem mostrá-los, ou desmarque todas para guardá-los para depois.',
  'simple.help.g3.s3': 'Cada foto aparece por 10 segundos; os vídeos tocam até o fim.',
  'simple.help.q1': 'O que posso usar como tela?',
  'simple.help.a1': 'TVs Android, TV boxes e tablets, Fire TV, smart TVs LG e Samsung, Raspberry Pi, Windows e ChromeOS, ou qualquer aparelho com navegador.',
  'simple.help.q2': 'Minha tela não muda. O que devo verificar?',
  'simple.help.a2': 'Confira se a tela aparece como “Exibindo” na página inicial. Se aparecer “Offline”, verifique se o aparelho está ligado e conectado à internet; ele recebe suas mudanças assim que se reconectar.',
  'simple.help.q3': 'O que acontece se a internet cair?',
  'simple.help.a3': 'As telas guardam o conteúdo localmente e continuam reproduzindo. As novas mudanças chegam quando a conexão voltar.',
  'simple.help.q4': 'Quais arquivos posso enviar?',
  'simple.help.a4': 'Fotos (JPEG, PNG, GIF, WebP) e vídeos (MP4 funciona melhor), além de áudio. PDFs podem ser enviados na página Conteúdo, na visão “Avançada”.',
  'simple.help.q5': 'Como renomeio ou removo uma tela?',
  'simple.help.a5': 'Mude para “Avançada” (no canto superior direito), abra “Telas”, clique na tela e use Renomear ou Remover no topo da página.',
  'simple.help.q6': 'Posso mostrar coisas diferentes em horários diferentes?',
  'simple.help.a6': 'Sim: isso é “Agenda”, na visão “Avançada”. A visão simples sempre mostra o mesmo conteúdo em uma tela até você mudar.',
  'simple.help.trial_q': 'Como funciona o teste grátis?',
  'simple.help.trial_a': 'Você tem 14 dias do plano Pro com todos os recursos, sem cartão. Ao terminar, você passa para o plano Free: nada é apagado, e as telas acima do limite do plano Free ficam pausadas até você escolher um plano.',
  'stats.prompt.title': 'Ajude a mostrar o quanto o ScreenTinker é usado?',
  'stats.prompt.body': 'Como a maioria das instalações é privada, não sabemos quantas telas existem. Ao compartilhar, enviamos um ID aleatório, a versão e quantas telas você usa, nada mais, nunca. Você pode mudar isso a qualquer momento em Configurações.',
  'stats.prompt.share': 'Compartilhar',
  'stats.prompt.no': 'Não, obrigado',
  'stats.prompt.thanks': 'Obrigado: estatísticas de instalação compartilhadas',
