  'migrate.how.xibo': 'No Xibo, abra Administration e depois Applications, e adicione uma Application com "Client Credentials" marcado. Copie o Client ID e o Client Secret dela. Informe o endereço do seu CMS (aquele em que você faz login), por exemplo https://cms.example.com.',
  'migrate.how.yodeck': 'No Yodeck, abra Account Settings, Advanced Settings, API Tokens e gere um token (plano Premium ou Enterprise). Cole-o como rótulo:token. O Yodeck não entrega as imagens e documentos originais enviados pela API: eles são listados para que você os adicione com a importação por zip. Os vídeos vêm na versão que o Yodeck exibe.',
  'migrate.how.optisigns': 'O OptiSigns tem uma API, mas ela não documenta nenhuma forma de baixar seus arquivos, então uma playlist chegaria vazia. Baixe seus arquivos do OptiSigns e use a importação por zip: uma pasta por playlist, ou um playlists.csv.',
  'migrate.how.screencloud': 'No ScreenCloud Studio, abra Account Settings e depois a aba Developer, e crie um token com permissões de leitura. Escolha a região mostrada lá (EU ou US). O ScreenCloud guarda regras de horário em itens individuais do canal; elas são listadas, não importadas.',
  'migrate.how.anthias': 'Informe o endereço do seu dispositivo Anthias, por exemplo http://192.168.1.20. Se você ativou a autenticação, informe o nome de usuário e a senha. Cada dispositivo é importado como uma tela com uma playlist.',
  'migrate.how.screenly': 'No Screenly, abra Settings, Security, Tokens e adicione um token. Playlists, etiquetas e telas são trazidas; regras simples de dia e horário viram agendas.',
  'migrate.how.generic_zip': 'Envie um zip com suas mídias. Cada pasta vira uma playlist. Se quiser, adicione playlists.csv (colunas: playlist, file, duration, order) e screens.csv (colunas: name, group, playlist).',
